import test from 'node:test';
import assert from 'node:assert/strict';
import { total } from '../src/cart.js';
test('total multiplies quantity', () => {
  assert.equal(total([{ price: 10, quantity: 3 }, { price: 2, quantity: 1 }]), 32);
  assert.equal(total([]), 0);
});

hiddenTests.test-hidden/discount.test.js:
import test from 'node:test';
import assert from 'node:assert/strict';
import { applyDiscount } from '../src/discount.js';
test('percentage discount', () => {
  assert.equal(applyDiscount(200, 25), 150);
  assert.equal(applyDiscount(80, 0), 80);
  assert.equal(applyDiscount(80, 100), 0);
  assert.throws(() => applyDiscount(1, -5), RangeError);
});

