import test from 'node:test';
import assert from 'node:assert/strict';
import { slugify } from '../src/slug.js';
test('lowercase slugs', () => {
  assert.equal(slugify('Hello,  World!'), 'hello-world');
  assert.equal(slugify('  ABC def '), 'abc-def');
});
